[{"order":1,"type":"heading","text":"Mastering Cloud Functions Triggers in Firebase Firestore"},{"order":2,"type":"paragraph","text":"Firebase Cloud Functions for Firestore allow you to execute server-side code in response to database events. Understanding how to use onCreate, onUpdate, and onDelete triggers is essential for building reactive, real-time backend logic such as data aggregation, notification dispatching, and audit logging."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed on your local development machine."},{"order":5,"type":"bullet_point","text":"Firebase CLI installed globally via npm install -g firebase-tools."},{"order":6,"type":"bullet_point","text":"A Firebase project with Firestore initialized in your project directory."},{"order":7,"type":"subheading","text":"1. The onCreate Trigger"},{"order":8,"type":"paragraph","text":"The onCreate trigger activates when a new document is created in Firestore. It is commonly used for initializing user profiles, sending welcome emails, or generating default metadata."},{"order":9,"type":"code","text":"const { functions, admin } = require('./index');

exports.onUserCreated = functions.firestore
  .document('users/{userId}')
  .onCreate((snap, context) => {
    const newValue = snap.data();
    const userId = context.params.userId;

    console.log('New user created:', userId, newValue);

    return snap.ref.set({
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      status: 'active'
    }, { merge: true });
  });"},{"order":10,"type":"subheading","text":"2. The onUpdate Trigger"},{"order":11,"type":"paragraph","text":"The onUpdate trigger fires when an existing document is modified. Unlike onCreate and onDelete, this function provides a Change object containing both the before and after states of the document."},{"order":12,"type":"code","text":"exports.onUserProfileUpdated = functions.firestore
  .document('users/{userId}')
  .onUpdate((change, context) => {
    const beforeData = change.before.data();
    const afterData = change.after.data();

    if (beforeData.status !== afterData.status) {
      console.log('User status changed from', beforeData.status, 'to', afterData.status);
    }

    return null;
  });"},{"order":13,"type":"subheading","text":"3. The onDelete Trigger"},{"order":14,"type":"paragraph","text":"The onDelete trigger executes when a document is permanently deleted from Firestore. It provides access to the final state of the document snapshot just before removal, making it ideal for cascading deletes or cleanup operations."},{"order":15,"type":"code","text":"exports.onUserDeleted = functions.firestore
  .document('users/{userId}')
  .onDelete(async (snap, context) => {
    const deletedData = snap.data();
    const userId = context.params.userId;

    console.log('User deleted:', userId);

    const userPostsRef = admin.firestore().collection('posts').where('authorId', '==', userId);
    const postsSnapshot = await userPostsRef.get();

    const batch = admin.firestore().batch();
    postsSnapshot.docs.forEach((doc) => {
      batch.delete(doc.ref);
    });

    return batch.commit();
  });"},{"order":16,"type":"subheading","text":"Best Practices"},{"order":17,"type":"bullet_point","text":"Always return a Promise or use async/await so Firebase knows when your function execution is complete."},{"order":18,"type":"bullet_point","text":"Watch out for infinite loops in onUpdate triggers by verifying that specific fields actually changed before writing back to Firestore."},{"order":19,"type":"bullet_point","text":"Use wildcards like {userId} to capture dynamic segments in your document paths."}]
